<?php declare(strict_types=1); $config=require __DIR__.'/config.php';$code=trim((string)($_GET['code']??''));try{$pdo=new PDO(sprintf('mysql:host=%s;port=%d;dbname=%s;charset=utf8mb4',$config['host'],$config['port'],$config['database']),$config['user'],$config['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$stmt=$pdo->prepare("SELECT codigo_pedido,cliente_nombre,monto_total,metodo_pago,estado_pago,estado_envio FROM pedidos WHERE codigo_pedido=?");$stmt->execute([$code]);$order=$stmt->fetch();if(!$order){http_response_code(404);exit('Pedido no encontrado.');}}catch(Throwable $e){http_response_code(500);exit('No se pudo consultar el pedido.');}function h(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pedido <?=h($order['codigo_pedido'])?></title><style>body{font-family:system-ui;background:#f6f3ee;margin:0}main{max-width:650px;margin:auto;padding:40px 20px}.card{background:#fff;padding:26px;border-radius:16px}</style></head><body><main><section class="card"><h1>Pedido recibido</h1><p>Hola, <?=h($order['cliente_nombre'])?>.</p><p>Código: <strong><?=h($order['codigo_pedido'])?></strong></p><p>Total: S/ <?=h((string)$order['monto_total'])?></p><p>Pago: <?=h($order['estado_pago'])?></p><p>Envío: <?=h($order['estado_envio'])?></p><p>Guarda tu código para consultar el seguimiento.</p><a href="/">Volver a la galería</a></section></main></body></html>
